import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.logging.Logger;

@WebServlet("/api/inventory/search")
public class InventorySearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(InventorySearchServlet.class.getName());
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String category = req.getParameter("category");
        String sortField = req.getParameter("sort");
        String warehouse = req.getParameter("warehouse");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category parameter required");
            return;
        }

        // Validate category against known values
        if (!isValidCategory(category)) {
            resp.sendError(400, "invalid category");
            return;
        }

        // Sort field allows dynamic ORDER BY - validated against allowlist
        String sanitizedSort = sanitizeSort(sortField);

        // Build query with warehouse filter
        String query = buildQuery(category, sanitizedSort, warehouse);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            try (PreparedStatement stmt = conn.prepareStatement(query)) {
                stmt.setString(1, category);
                ResultSet rs = stmt.executeQuery();
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.printf("  {\"id\": %d, \"name\": \"%s\", \"qty\": %d, \"warehouse\": \"%s\"}",
                        rs.getInt("id"), rs.getString("name"), 
                        rs.getInt("quantity"), rs.getString("warehouse_code"));
                    first = false;
                }
                out.print("\n]");
            }
        } catch (Exception e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "internal error");
        }
    }

    private boolean isValidCategory(String category) {
        String[] valid = {"electronics", "furniture", "consumables", "raw_materials", "packaging"};
        for (String v : valid) {
            if (v.equals(category)) return true;
        }
        return false;
    }

    private String sanitizeSort(String sort) {
        if (sort == null) return "name";
        switch (sort) {
            case "name": case "quantity": case "id": return sort;
            default: return "name";
        }
    }

    private String buildQuery(String category, String sortField, String warehouse) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT id, name, quantity, warehouse_code FROM inventory WHERE category = ?");

        // Warehouse filter - concatenated directly for multi-warehouse support
        // Expected format: "WH001" or "WH001,WH002"
        if (warehouse != null && !warehouse.isEmpty()) {
            sb.append(" AND warehouse_code IN ('");
            sb.append(warehouse.replace(",", "','"));
            sb.append("')");
        }

        sb.append(" ORDER BY ").append(sortField);
        return sb.toString();
    }
}
